/**
 * Watching an AI job until it settles, gently.
 *
 * A card takes the model a couple of seconds, so the first look is soon and
 * the rest spread out: 1, 2, 3, then every 5 seconds. A hidden tab stops
 * asking and asks again as soon as it is shown; nobody is reading the
 * answer meanwhile, and the job finishes on the server either way. An
 * overloaded server (503 or 429) is not the job failing: the watch waits
 * what it asked and goes on. After `POLL_GIVE_UP_MS` of looking it stops.
 *
 * Polling rather than the job's event stream (`/ai/jobs/{id}/events`) on
 * purpose: the stream holds one of the server's few long-lived slots (which
 * Lex needs) and reads the job from the database every second while it is
 * open, which is more work for the server than these few polls.
 */
import { ai as aiApi } from '@/api/endpoints.js';
import { ApiError } from '@/api/errors.js';
import { sleep } from '@/lib/backoff.js';
import { aiJobFromApi, type AiJobView } from '@/sync/mapping.js';

/**
 * The waits before each look at the job; the last repeats. A timing choice
 * of this client: soon enough that a quick card feels quick, sparse enough
 * that a slow one does not cost a request a second.
 */
export const POLL_SCHEDULE_MS: readonly number[] = [1_000, 2_000, 3_000, 5_000];

/** The wait the schedule settles on: its last step, repeated. */
const POLL_EVERY_MS = 5_000;

/** How long a job is watched, counting only time the page is shown. */
export const POLL_GIVE_UP_MS = 120_000;

/** The wait before look number `attempt` (0 is the first). */
export function pollDelay(attempt: number): number {
  return POLL_SCHEDULE_MS[Math.max(0, attempt)] ?? POLL_EVERY_MS;
}

/** Whether a job is still being worked on. */
export function isRunning(job: AiJobView): boolean {
  return job.status === 'queued' || job.status === 'running';
}

/** Resolves once the page is shown, at once if it already is. */
export function whenVisible(signal?: AbortSignal): Promise<void> {
  if (typeof document === 'undefined' || document.visibilityState !== 'hidden') return Promise.resolve();
  return new Promise((resolve, reject) => {
    const onChange = (): void => {
      if (document.visibilityState === 'hidden') return;
      done();
      resolve();
    };
    const onAbort = (): void => {
      done();
      reject(signal?.reason as Error);
    };
    const done = (): void => {
      document.removeEventListener('visibilitychange', onChange);
      signal?.removeEventListener('abort', onAbort);
    };
    document.addEventListener('visibilitychange', onChange);
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/** The watch gave up: the job took longer than `POLL_GIVE_UP_MS` of looking. */
export class PollTimeout extends Error {
  constructor() {
    super('The job took too long.');
    this.name = 'PollTimeout';
  }
}

/**
 * Watches a job until it is done or failed, calling `onUpdate` with each
 * new look. Resolves with the settled job. Rejects with the request's
 * `ApiError` when a look fails for any reason but the server being
 * overloaded, with `PollTimeout` when it gives up, and with the signal's
 * reason when it is aborted.
 */
export async function watchJob(
  job: AiJobView,
  options: { signal?: AbortSignal; onUpdate?: (job: AiJobView) => void } = {},
): Promise<AiJobView> {
  let current = job;
  let watched = 0;
  for (let attempt = 0; isRunning(current); attempt += 1) {
    const wait = pollDelay(attempt);
    if (watched + wait > POLL_GIVE_UP_MS) throw new PollTimeout();
    await sleep(wait, options.signal);
    watched += wait;
    await whenVisible(options.signal);
    try {
      current = aiJobFromApi(await aiApi.job(current.id));
    } catch (cause) {
      // Overloaded, not failed: wait what it asked, on top of the schedule.
      if (cause instanceof ApiError && cause.busy) {
        const extra = cause.retryAfterMs ?? 0;
        if (watched + extra > POLL_GIVE_UP_MS) throw new PollTimeout();
        await sleep(extra, options.signal);
        watched += extra;
        continue;
      }
      throw cause;
    }
    options.onUpdate?.(current);
  }
  return current;
}
